-- PT101-S3-Q21. Batch 12.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch12$PT101-S3-Q21$batch12$ AND q.stimulus=$batch12$The amount of electricity consumed in Millville on any day in August is directly proportional to peak humidity on that day. Since the average peak humidity this August was three points higher than the average peak humidity last August, it follows that more energy was consumed in Millville this August than last August.$batch12$ AND q.prompt=$batch12$Which one of the following arguments has a pattern of reasoning most similar to the one in the argument above?$batch12$ AND q.correct_choice=$batch12$A$batch12$) THEN RAISE EXCEPTION 'Question changed: PT101-S3-Q21'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch12$PT101-S3-Q21$batch12$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT101-S3-Q21'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch12$PT101-S3-Q21$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch12$Conclusion$batch12$, $batch12$Millville used more electricity this August than last August.$batch12$), (1, $batch12$Evidence$batch12$, $batch12$Each day's electricity use is directly proportional to that day's peak humidity. Average peak humidity was higher this August.$batch12$), (2, $batch12$Evaluate$batch12$, $batch12$Recipe: a quantity in each unit is proportional to a factor in that unit. The factor averaged higher this period than last. So the total quantity was higher this period. Look for the same pieces: per-unit proportion, comparison of the factor across two periods, conclusion about the total.$batch12$), (3, $batch12$Goal$batch12$, $batch12$Per-unit proportion, factor higher overall this period, so the total is higher this period.$batch12$)) v(position,label,body) WHERE q.qid=$batch12$PT101-S3-Q21$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch12$A$batch12$, $batch12$Supplies in each class are proportional to that class's students. More students overall last year, so more supplies last year. Every piece lines up.$batch12$), ($batch12$B$batch12$, $batch12$This compares painting courses with sculpture courses, not one quantity across two periods.$batch12$), ($batch12$C$batch12$, $batch12$This ends in a recommendation about what the institute must do, not a comparison of totals.$batch12$), ($batch12$D$batch12$, $batch12$Fees are proportional to the number of classes per student, but the evidence is about the number of students. The factor in the evidence isn't the one in the proportion.$batch12$), ($batch12$E$batch12$, $batch12$This links two proportions to a third. It never compares two periods.$batch12$)) v(letter,body) WHERE q.qid=$batch12$PT101-S3-Q21$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
